const body = msg.payload;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };
const acoes = ['mensagem', 'boas-vindas', 'retransmitir'];
const origem = msg.req.headers.origin;
const origemOk = !origem || origem === 'http://' + msg.req.headers.host;
if (!origemOk || !body || typeof body.sessionId !== 'string' || !/^[A-Za-z0-9_-]{22,80}$/.test(body.sessionId) ||
    !acoes.includes(body.acao) ||
    (body.acao === 'mensagem' && (typeof body.texto !== 'string' || !body.texto.trim() || body.texto.length > 500))) {
  msg.statusCode = 400;
  msg.payload = { erro: 'Entrada inválida. Recarregue a página e tente novamente.' };
  return [null, msg];
}
msg.nexus = { dono: 'web:' + body.sessionId, acao: body.acao,
  texto: body.texto, rotaAtiva: body.rotaAtiva === true };
return [msg, null];

const engine = global.get('nexusEngine');
const cfg = global.get('nexusConfig');
if (!engine) {
  msg.statusCode = 503;
  msg.payload = { erro: 'Inicie o projeto com npm start para carregar settings.cjs.' };
  if (msg.req) return [msg, null];
  node.warn('Módulo NEXUS não carregado.');
  return null;
}
const sessoes = flow.get('sessoesNexus') || {};
const agora = Date.now();
for (const k of Object.keys(sessoes)) {
  if (agora - sessoes[k].ultima > 1800000 && !sessoes[k].estado.ocupada) delete sessoes[k];
}
const chave = msg.nexus.dono;
if (!sessoes[chave]) sessoes[chave] = { estado: engine.novaSessao() };
sessoes[chave].ultima = agora;
flow.set('sessoesNexus', sessoes);
msg.payload = await engine.conversar(cfg, sessoes[chave].estado, msg.nexus);
return msg.req ? [msg, null] : [null, msg];

try {
  const tg = global.get('nexusTelegram');
  if (!tg) return null;
  const mensagens = await tg.consultar();
  return [mensagens.map(m => ({ tg: { chat: m.chat.id, voz: m.voice }, payload: m.text }))];
} catch { node.warn('Telegram indisponível. Verifique conexão e token local.'); return null; }

const tg = global.get('nexusTelegram');
if (msg.tg.voz) {
  try {
    if (msg.tg.voz.duration > 30) {
      await tg.enviarTexto(msg.tg.chat, 'Use texto ou envie uma mensagem de voz de até 30 segundos.');
      return null;
    }
    msg.payload = await tg.transcrever(msg.tg.voz);
  } catch {
    try { await tg.enviarTexto(msg.tg.chat, 'Não consegui transcrever o áudio. Envie a resposta escrita.'); } catch {}
    return null;
  }
}
const texto = typeof msg.payload === 'string' ? msg.payload.trim() : '';
if (!texto || texto.length > 500) {
  try { await tg.enviarTexto(msg.tg.chat, 'Envie uma mensagem de até 500 caracteres.'); } catch {}
  return null;
}
// Um áudio nunca confirma o registro: a transcrição pode estar errada.
if (msg.tg.voz && global.get('nexusEngine').normalizar(texto) === 'confirmar registro') {
  try { await tg.enviarTexto(msg.tg.chat, 'Por segurança, digite Confirmar registro após conferir os dados.'); } catch {}
  return null;
}
msg.nexus = { dono: 'telegram:' + msg.tg.chat, acao: texto === '/start' ? 'boas-vindas' : 'mensagem', texto };
return msg;

const tg = global.get('nexusTelegram');
let resposta = msg.payload.resposta;
if (msg.nexus.acao === 'boas-vindas') resposta += '\n\nUse dados fictícios. As respostas de voz são geradas por IA. Os áudios enviados para transcrição passam por um serviço externo.';
if (msg.payload.sugestoes.length) resposta += '\n\nOpções: ' + msg.payload.sugestoes.join(' · ');
try {
  await tg.enviarTexto(msg.tg.chat, resposta);
  if (!msg.tg.voz) return null;
  // O TTS lê apenas a próxima etapa, sem enviar a localização de volta ao serviço de voz.
  msg.fala = ({ evento: 'Escolha o tipo de emergência.', localizacao: 'Informe um endereço ou ponto de referência.',
    pessoas: 'Informe a quantidade de pessoas ou diga não sei.', risco: 'Há risco imediato?',
    confirmar: 'Confira o resumo escrito e digite confirmar registro quando estiver correto.',
    protocolo: 'Informe seu protocolo ou diga último pedido.' })[msg.payload.etapa] ||
    'Veja a resposta completa do NEXUS na mensagem de texto.';
  return msg;
} catch { node.warn('Não foi possível responder ao Telegram.'); return null; }

try { await global.get('nexusTelegram').enviarVoz(msg.tg.chat, msg.fala); }
catch { node.warn('A síntese de voz falhou. A resposta escrita já foi enviada.'); }
return null;
